import glob
import os

def main():
    # Find all test files generated by the benchmark
    testFiles = glob.glob(os.path.join("results", "*", "*_test.txt"))
    
    if not testFiles:
        print("No test files found in results/ directory. Please run the benchmark first.")
        return

    failuresFound = False

    print(f"\n{'='*50}\nTest Verification Results\n{'='*50}")
    for file in testFiles:
        with open(file, 'r') as f:
            content = f.read().strip()
            # If the file contains the failure message, flag it
            if "Verification failed" in content:
                print(f"[FAILED] File: {file}")
                print(f"         Details: {content}")
                failuresFound = True

    if not failuresFound:
        print(f"All {len(testFiles)} algorithm test cases passed successfully! No data corruption detected.")
    print("="*50 + "\n")

if __name__ == "__main__":
    main()